    fn standard() -> Self {
        Self {
            max_records: 10_000,
            prefer_filename_match: true,
            accept_unknown_targets: true,
        }
    }
}

#[derive(Debug, Clone)]
struct FirstLineRules {
    max_bytes: usize,
    allow_empty: bool,
    inspect_shebang: bool,
    inspect_modeline: bool,
}

impl FirstLineRules {
    fn standard() -> Self {
        Self {
            max_bytes: 1_048_576,
            allow_empty: true,
            inspect_shebang: true,
            inspect_modeline: true,
        }
